def memusage(_proc_pid_stat=None):
        """
        Return virtual memory size in bytes of the running python.

        """
        _proc_pid_stat = _proc_pid_stat or f'/proc/{os.getpid()}/stat'
        try:
            with open(_proc_pid_stat, encoding='utf-8') as f:
                l = f.readline().split(' ')
            return int(l[22])
        except Exception:
            return

def _to_real_if_imag_zero(w, t):
    """Backwards compat helper: force w to be real if t.dtype is real and w.imag == 0
    """
    result_t = t.dtype.type
    if not isComplexType(result_t) and all(w.imag == 0.0):
        w = w.real
        result_t = _realType(result_t)
    else:
        result_t = _complexType(result_t)
    return w.astype(result_t, copy=False)

