def iter_contained_typevars(v: Any) -> Iterator[TypeVarType]:
    """Recursively iterate through all subtypes and type args of `v` and yield any typevars that are found."""
    if isinstance(v, TypeVar):
        yield v
    elif hasattr(v, '__parameters__') and not get_origin(v) and lenient_issubclass(v, GenericModel):
        yield from v.__parameters__
    elif isinstance(v, (DictValues, list)):
        for var in v:
            yield from iter_contained_typevars(var)
    else:
        args = get_args(v)
        for arg in args:
            yield from iter_contained_typevars(arg)

def _get_timeout(self, timeout: _TYPE_TIMEOUT) -> Timeout:
        """Helper that always returns a :class:`urllib3.util.Timeout`"""
        if timeout is _DEFAULT_TIMEOUT:
            return self.timeout.clone()

        if isinstance(timeout, Timeout):
            return timeout.clone()
        else:
            # User passed us an int/float. This is for backwards compatibility,
            # can be removed later
            return Timeout.from_float(timeout)

def _get_all_fixture_defs_for_node(
        self, node: nodes.Node
    ) -> Iterable[FixtureDef[Any]]:
        """Get all FixtureDefs visible to a node.

        The order is not guaranteed.
        """
        for node2fixturedefs in self._arg2node2fixturedefs.values():
            for parent in node.iter_parents():
                yield from node2fixturedefs.get(parent, ())
        for nodeid2fixturedefs in self._arg2nodeid2fixturedefs.values():
            for parent in node.iter_parents():
                yield from nodeid2fixturedefs.get(parent.nodeid, ())

def _has_top_level_pipe(regex: str) -> bool:
    """Whether ``regex`` contains a ``|`` at the top level.

    A top-level ``|`` is one that is not backslash-escaped, not inside a
    ``(...)`` group, and not inside a ``[...]`` character class -- i.e. a real
    alternation between separate messages rather than an inline ``(a|b)``.
    """
    depth = 0
    in_character_class = False
    index = 0
    while index < len(regex):
        char = regex[index]
        if char == "\\\\":
            index += 2
            continue
        if in_character_class:
            if char == "]":
                in_character_class = False
        elif char == "[":
            in_character_class = True
        elif char == "(":
            depth += 1
        elif char == ")":
            depth = max(0, depth - 1)
        elif char == "|" and depth == 0:
            return True
        index += 1
    return False

def _gen_non_null_counts(self) -> Iterator[str]:
        """Iterator with string representation of non-null counts."""
        for count in self.non_null_counts:
