def _return_annotation_match(LL: list[Leaf]) -> int | None:
        """Return the string index for a stringified return annotation."""
        is_valid_index = is_valid_index_factory(LL)

        for i, leaf in enumerate(LL):
            if leaf.type != token.RARROW:
                continue

            string_idx = (
                i + 2 if is_valid_index(i + 1) and is_empty_lpar(LL[i + 1]) else i + 1
            )
            if not is_valid_index(string_idx) or LL[string_idx].type != token.STRING:
                return None

            idx = StringParser().parse(LL, string_idx)
            if (
                is_valid_index(idx)
                and LL[idx].type == token.COLON
                and idx == len(LL) - 1
            ):
                return string_idx

            return None

        return None

def ge(self: _Pipeline[_InT, _NewOutGe], ge: _NewOutGe) -> _Pipeline[_InT, _NewOutGe]:
        """Constrain a value to be greater than or equal to a certain value."""
        return self.constrain(annotated_types.Ge(ge))

def is_stationary(self):
        """Returns whether the kernel is stationary."""
        return self.metric in ["rbf"]

def _format_values_line(fmt_values: list[str], max_width: int) -> str:
        """Format a list of values into a bracketed, width-respecting string."""
        if max_width == 0:
            return "[" + ", ".join(fmt_values) + "]"

        parts = ["["]
        cur_col_len = 1  # account for the opening bracket
        start = True
        for val in fmt_values:
            if not start:
                if cur_col_len + 2 + len(val) > max_width:
                    parts.append(",\\n ")
                    cur_col_len = 1  # 1 space indent
                else:
                    parts.append(", ")
                    cur_col_len += 2
            parts.append(val)
            cur_col_len += len(val)
            start = False
        parts.append("]")
        return "".join(parts)

def stop(self) -> None:
        """Stop live rendering display."""
        with self._lock:
            if not self._started:
                return
            self._started = False
            self.console.clear_live()
            if self._nested:
                if not self.transient:
                    self.console.print(self.renderable)
                return

            if self.auto_refresh and self._refresh_thread is not None:
                self._refresh_thread.stop()
                self._refresh_thread = None
            # allow it to fully render on the last even if overflow
            self.vertical_overflow = "visible"
            with self.console:
                try:
                    if not self._alt_screen and not self.console.is_jupyter:
                        self.refresh()
                finally:
                    self._disable_redirect_io()
                    self.console.pop_render_hook()
                    if (
                        not self._alt_screen
                        and self.console.is_terminal
                        and self._live_render.last_render_height
                    ):
                        self.console.line()
                    self.console.show_cursor(True)
                    if self._alt_screen:
                        self.console.set_alt_screen(False)
                    if self.transient and not self._alt_screen:
                        self.console.control(self._live_render.restore_cursor())
                    if self.ipy_widget is not None and self.transient:
                        self.ipy_widget.close()

def _check_X(self, X):
        """Validate X, used only in predict* methods."""
        X = super()._check_X(X)
        if self.binarize is not None:
            X = binarize(X, threshold=self.binarize)
        return X

def to_array(obj: Any) -> ExtensionArray | np.ndarray:
    """
    Similar to pd.array, but does not cast numpy dtypes to nullable dtypes.
    """
    # temporary implementation until we get pd.array in place
    dtype = getattr(obj, "dtype", None)

    if dtype is None:
        return np.asarray(obj)

    return extract_array(obj, extract_numpy=True)

def setitem(self, indexer, value) -> Self:
        """
        Set values with indexer.

        For SingleBlockManager, this backs s[indexer] = value
        """
        if isinstance(indexer, np.ndarray) and indexer.ndim > self.ndim:
            raise ValueError(f"Cannot set values with ndim > {self.ndim}")

        if not self._has_no_reference(0):
            # this method is only called if there is a single block -> hardcoded 0
            # Split blocks to only copy the columns we want to modify
            if self.ndim == 2 and isinstance(indexer, tuple):
                blk_loc = self.blklocs[indexer[1]]
                if is_list_like(blk_loc) and blk_loc.ndim == 2:
                    blk_loc = np.squeeze(blk_loc, axis=0)
                elif not is_list_like(blk_loc):
                    # Keep dimension and copy data later
                    blk_loc = [blk_loc]  # type: ignore[assignment]
                if len(blk_loc) == 0:
                    return self.copy(deep=False)

                values = self.blocks[0].values
                if values.ndim == 2:
                    # Block.delete in _iset_split_block requires sorted unique
                    # locs; inverse maps the requested column order onto the
                    # new block (GH#65446)
                    blk_loc, inverse = np.unique(blk_loc, return_inverse=True)
                    values = values[blk_loc]
                    # "T" has no attribute "_iset_split_block"
                    self._iset_split_block(  # type: ignore[attr-defined]
                        0, blk_loc, values
                    )

                    indexer = list(indexer)
                    # first block equals values we are setting to -> set to all columns
                    if lib.is_integer(indexer[1]):
                        col_indexer = 0
                    elif len(inverse) > 1 and lib.is_range_indexer(
                        inverse, len(blk_loc)
                    ):
                        col_indexer = slice(None)  # type: ignore[assignment]
                    else:
                        col_indexer = inverse  # type: ignore[assignment]
                    indexer[1] = col_indexer

                    row_indexer = indexer[0]
                    if isinstance(col_indexer, np.ndarray):
                        if (
                            isinstance(row_indexer, np.ndarray)
                            and row_indexer.ndim == 1
                        ):
                            # GH#65446: Make the row indexer 2d to take a cross product
                            row_indexer = row_indexer[:, None]
                    elif isinstance(row_indexer, np.ndarray) and row_indexer.ndim == 2:
                        # numpy cannot handle a 2d indexer in combo with a slice
                        row_indexer = np.squeeze(row_indexer, axis=1)
                    if isinstance(row_indexer, np.ndarray) and len(row_indexer) == 0:
                        # numpy does not like empty indexer combined with slice
                        # and we are setting nothing anyway
                        return self
                    indexer[0] = row_indexer
                    self.blocks[0].setitem(tuple(indexer), value)
                    return self
            # No need to split if we either set all columns or on a single block
            # manager
            self = self.copy(deep=True)

        return self.apply("setitem", indexer=indexer, value=value)

def _sum_prod_no_axis(x: Array, dtype: DType | None) -> Array:
    """
    Implements `sum(..., axis=())` and `prod(..., axis=())`.

    Works around https://github.com/pytorch/pytorch/issues/29137
    """
    if dtype is not None:
        return x.clone() if dtype == x.dtype else x.to(dtype)

    # We can't upcast uint8 according to the spec because there is no
    # torch.uint64, so at least upcast to int64 which is what prod does
    # when axis=None.
    if x.dtype in (torch.uint8, torch.int8, torch.int16, torch.int32):
        return x.to(torch.int64)

    return x.clone()

def _get_modulus_pack(self):
