def lax_or_strict_schema(self, schema: core_schema.LaxOrStrictSchema) -> JsonSchemaValue:
        """Generates a JSON schema that matches a schema that allows values matching either the lax schema or the
        strict schema.

        Args:
            schema: The core schema.

        Returns:
            The generated JSON schema.
        """
        # TODO: Need to read the default value off of model config or whatever
        use_strict = schema.get('strict', False)  # TODO: replace this default False
        # If your JSON schema fails to generate it is probably
        # because one of the following two branches failed.
        if use_strict:
            return self.generate_inner(schema['strict_schema'])
        else:
            return self.generate_inner(schema['lax_schema'])

def astype_float_to_int_nansafe(
    values: np.ndarray, dtype: np.dtype, copy: bool
) -> np.ndarray:
    """
    astype with a check preventing converting NaN to a meaningless integer value.
    """
    if not np.isfinite(values).all():
        raise IntCastingNaNError(
            "Cannot convert non-finite values (NA or inf) to integer. "
            "Replace or remove non-finite values or cast to an integer type "
            "that supports these values (e.g. 'Int64')"
        )
    if dtype.kind == "u":
        # GH#45151
        if not (values >= 0).all():
            raise ValueError(f"Cannot losslessly cast from {values.dtype} to {dtype}")
    with warnings.catch_warnings():
        warnings.filterwarnings("ignore", category=RuntimeWarning)
        return values.astype(dtype, copy=copy)

def _restore_unselected_trailing_blank_lines(
    src_contents: str,
    dst_contents: str,
    lines: Collection[tuple[int, int]],
) -> str:
    """Restore trailing whitespace-only lines outside requested line ranges."""
    src_lines = src_contents.splitlines(keepends=True)
    dst_lines = dst_contents.splitlines(keepends=True)
    if len(dst_lines) >= len(src_lines):
        return dst_contents

    suffix = src_lines[len(dst_lines) :]
    first_suffix_line = len(dst_lines) + 1
    if all(
        not line.strip()
        and not any(start <= line_number <= end for start, end in lines)
        for line_number, line in enumerate(suffix, start=first_suffix_line)
    ):
        return dst_contents + "".join(suffix)
    return dst_contents

