def _make_ansi_codes(self, color_system: ColorSystem) -> str:
        """Generate ANSI codes for this style.

        Args:
            color_system (ColorSystem): Color system.

        Returns:
            str: String containing codes.
        """

        if self._ansi is None:
            sgr: List[str] = []
            append = sgr.append
            _style_map = self._style_map
            attributes = self._attributes & self._set_attributes
            if attributes:
                if attributes & 1:
                    append(_style_map[0])
                if attributes & 2:
                    append(_style_map[1])
                if attributes & 4:
                    append(_style_map[2])
                if attributes & 8:
                    append(_style_map[3])
                if attributes & 0b0000111110000:
                    for bit in range(4, 9):
                        if attributes & (1 << bit):
                            append(_style_map[bit])
                if attributes & 0b1111000000000:
                    for bit in range(9, 13):
                        if attributes & (1 << bit):
                            append(_style_map[bit])
            if self._color is not None:
                sgr.extend(self._color.downgrade(color_system).get_ansi_codes())
            if self._bgcolor is not None:
                sgr.extend(
                    self._bgcolor.downgrade(color_system).get_ansi_codes(
                        foreground=False
                    )
                )
            self._ansi = ";".join(sgr)
        return self._ansi

def _should_keep_compound_statement_inline(
    body_node: Node, simple_stmt_parent: Node
) -> bool:
    """Check if a compound statement should be kept on one line.

    Returns True only for compound statements with semicolon-separated bodies,
    like: if True: print("a"); print("b")  # fmt: skip
    """
    # Narrow down to the single simple_stmt that may carry the semicolons before
    # scanning any leaves. A compound statement's suite holds one child per body
    # statement, so walking the whole suite here is O(n) and, called once per
    # `# fmt: skip` line in the block, makes the pass O(n^2).
    if body_node.type == syms.suite:
        # After formatting: the suite must hold exactly one simple_stmt and it
        # must be the one carrying the directive. Stop at the second simple_stmt.
        target: LN | None = None
        for child in body_node.children:
            if child.type == syms.simple_stmt:
                if target is not None:
                    return False
                target = child
        if target is None or target is not simple_stmt_parent:
            return False
    else:
        # Original form: body_node IS the simple_stmt
        if body_node is not simple_stmt_parent:
            return False
        target = body_node

    return any(leaf.type == token.SEMI for leaf in target.leaves())

def _def_is_followed_by_same_name_decorated_func(
        line: Line, *, include_conditional_blocks: bool = False
    ) -> bool:
        """Check if a decorated function is followed by a same-name decorated func.

        If *include_conditional_blocks* is true, the next decorated function may
        be inside an adjacent conditional block.
        """
        name = EmptyLineTracker._get_def_name(line)
        decorated = EmptyLineTracker._find_decorated_node(line)
        if name is None or decorated is None:
            return False

        sibling = decorated.next_sibling
        while sibling is not None and sibling.type in _WHITESPACE_TOKENS:
            sibling = sibling.next_sibling

        if sibling is None or not isinstance(sibling, Node):
            return False
        if sibling.type == syms.decorated:
            return EmptyLineTracker._decorated_node_has_func_named(sibling, name)
        if not include_conditional_blocks or sibling.type != syms.if_stmt:
            return False
        for child in sibling.children:
            if not isinstance(child, Node):
                continue
            if child.type != syms.suite:
                continue
            first_decorated_funcname = (
                EmptyLineTracker._get_suite_first_decorated_funcname(child)
            )
            return first_decorated_funcname == name
        return False

